program = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    key_colors = {grid[r][c] for r in range(min(4, h)) for c in range(min(4, w))
                  if grid[r][c] not in (0, 3, 7)}
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if seen[r][c] or grid[r][c] == 7:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 7:
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            if any(y < 4 and x < 4 for y, x in cells):
                continue
            colors = {grid[y][x] for y, x in cells if grid[y][x] != 0}
            if key_colors <= colors:
                for y, x in cells:
                    out[y][x] = 7
    return out
'''
